import type { Register } from 'claude-code'

const PANE = 'sessions'
const DIR = `${process.env.HOME}/.claude/session-dashboard`

type Row = { id: string; title: string; cwd: string; state: 'working' | 'waiting' | 'done' | 'ended'; at: number }

const LABEL = { working: 'trabalhando', waiting: 'esperando resposta', done: 'concluída', ended: 'encerrada' } as const
const COLOR = { working: 'yellow', waiting: 'red', done: 'green', ended: 'gray' } as const

let me: Row | null = null

async function save($: any, state: Row['state']) {
  if (!me) return
  me = { ...me, state, at: await $.clock.now() }
  await $.fs.write(`${DIR}/${me.id}.json`, JSON.stringify(me))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    me = { id: await $.session.id(), title: 'nova sessão', cwd: await $.session.cwd(), state: 'done', at: 0 }
    await save($, 'done')
    await $.command.register({ name: 'sessoes', description: 'Painel com as sessões ativas e o status de cada uma' })
    $.clock.every(2000, () => $.ui.invalidate('ui.render'))

    return next(e)
  })

  on('command.run', { command: 'sessoes' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Sessões' })

    return { text: 'Painel de sessões aberto.' }
  })

  on('prompt.submit', async ($, e, next) => {
    if (me) me = { ...me, title: e.text.replace(/\s+/g, ' ').slice(0, 60) }
    await save($, 'working')

    return next(e)
  })

  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    await save($, 'waiting')
    const r = await next(e)
    await save($, 'working')

    return r
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) await save($, 'done')

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    await save($, 'ended')

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const now = await $.clock.now()
    const rows: Row[] = []
    for (const f of await $.fs.list(DIR).catch(() => [])) {
      if (!f.name.endsWith('.json')) continue
      try {
        rows.push(JSON.parse(await $.fs.read(`${DIR}/${f.name}`)))
      } catch {}
    }
    const live = rows.filter(r => r.state !== 'ended' || now - r.at < 10 * 60_000).sort((a, b) => b.at - a.at)
    const count = (s: Row['state']) => live.filter(r => r.state === s).length

    return (
      <Box flexDirection="column">
        <Text bold>
          {count('working')} trabalhando · {count('waiting')} esperando · {count('done')} concluídas
        </Text>
        {live.length === 0 && <Text dimColor>Nenhuma sessão ainda.</Text>}
        {live.map(r => (
          <Box key={r.id} flexDirection="column" marginTop={1}>
            <Text color={COLOR[r.state]}>
              ● {LABEL[r.state]}
              {r.id === me?.id ? '  (esta)' : ''}
            </Text>
            <Text>{r.title}</Text>
            <Text dimColor>{r.cwd.split('/').slice(-2).join('/')}</Text>
          </Box>
        ))}
      </Box>
    )
  })
}

